<script setup lang="ts">
import {ref,onMounted} from 'vue';import {get} from '../../../../packages/shared/src/client';import {useOperations} from '../../../../packages/shared/src/operations';import {useTask,type Row} from '../../../../packages/shared/src/ui';import Status from '../../../../packages/shared/src/Status.vue';
const task=useTask(),ops=useOperations(),seasons=ref<Row[]>([]),month=ref(''),points=ref<Row[]>([]),rules=ref<Row[]>([]),rewards=ref<Row[]>([]),rewardPage=ref(1),rewardTotal=ref(0),editing=ref<Row>(),coupons=ref<Row[]>([]);
const rewardStatus=(value:unknown)=>({PENDING:'发放中',FAILED:'待处理',FULFILLED:'已发放'}[String(value)]||'待核对');
const status=(value:unknown)=>({LEGACY_READONLY:'历史赛季',OPEN:'进行中',SETTLING:'结算中',BLOCKED:'等待核对',SETTLED:'已结算'}[String(value)]||String(value));
async function details(){await task.run(async()=>{const [a,b,c]=await Promise.all([get<Row>('/learning-hub/admin/reward-rules?month='+month.value),get<Row>('/learning-hub/admin/rewards?month='+month.value+'&pageNo='+rewardPage.value+'&pageSize=20'),get<Row>('/learning-hub/admin/points-statistics?month='+month.value)]);rules.value=(a.list||[]).map((r:Row)=>({...r,enabled:!!r.enabled}));rewards.value=b.list||[];rewardTotal.value=Number(b.total||0);points.value=c.list||[];});}
async function load(){await task.run(async()=>{const data=await get<Row>('/learning-hub/admin/seasons');seasons.value=data.list||[];month.value=month.value||String(seasons.value[0]?.month||'');});if(month.value)await details();}
async function save(){const ok=await task.run(async()=>{if(!editing.value)return false;const row=editing.value;const op=await ops.begin('learning','保存赛季奖励规则','/learning-hub/admin/reward-rules/'+row.id,{month:month.value,rankFrom:row.rankFrom,rankTo:row.rankTo,couponId:row.couponId,enabled:row.enabled,version:row.version},'PUT');if(op.status==='SUCCEEDED'){editing.value=undefined;return true;}return false;});if(ok){await details();task.message.value='奖励规则已保存';}}
async function retry(row:Row){const ok=await task.run(async()=>{const op=await ops.begin('learning','重试赛季发奖','/learning-hub/admin/rewards/'+row.requestId+'/retry',{});return op.status==='SUCCEEDED';});if(ok){await details();task.message.value='奖励重试已处理';}}
const editable=()=>month.value>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).format(new Date()).replace('-','');
onMounted(async()=>{await load();await task.run(async()=>{const data=await get<Row>('/admin/promotion/coupons/page?pageNo=1&pageSize=100');coupons.value=data.list||[];});});
</script><template><section class="card"><div class="section-heading"><div><h1>赛季与奖励</h1><p>自然月赛季。开始后锁定奖励规则，发放结果可追踪。</p></div><el-button @click="load" :disabled="task.busy.value">刷新状态</el-button></div><Status :busy="task.busy.value" :error="task.error.value" :message="task.message.value"/><el-select v-model="month" aria-label="管理赛季" @change="rewardPage=1;details()"><el-option v-for="season in seasons" :key="season.month" :label="season.name+' · '+status(season.status)" :value="season.month"/></el-select><p v-for="season in seasons.filter(x=>x.month===month)" :key="season.month">{{status(season.status)}}<span v-if="season.blockedReason"> · {{season.blockedReason}}</span><span v-if="season.settledAt"> · 最终结算 {{season.settledAt}}</span></p><h2>积分来源</h2><el-table :data="points" empty-text="本赛季暂无积分事实"><el-table-column prop="typeName" label="来源"/><el-table-column prop="points" label="累计积分"/><el-table-column prop="events" label="奖励次数"/><el-table-column prop="students" label="参与人数"/></el-table><div class="section-heading"><h2>奖励规则</h2><el-button :disabled="!editable()" @click="editing={id:'0',rankFrom:1,rankTo:1,couponId:'',enabled:false,version:0}">新增奖励档位</el-button></div><p class="muted">默认不启用发券。名次区间不可重叠；仅未来赛季允许修改。</p><el-table :data="rules" empty-text="本赛季未配置优惠券奖励"><el-table-column label="名次"><template #default="{row}">{{row.rankFrom}}–{{row.rankTo}}</template></el-table-column><el-table-column prop="couponId" label="优惠券编号"/><el-table-column label="状态"><template #default="{row}">{{row.enabled?'已启用':'未启用'}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button :disabled="!editable()" @click="editing={...row}">编辑</el-button></template></el-table-column></el-table><h2>发放记录</h2><el-table :data="rewards" empty-text="暂无发放记录"><el-table-column prop="seasonMonth" label="赛季"/><el-table-column prop="rankNo" label="名次"/><el-table-column label="状态"><template #default="{row}">{{rewardStatus(row.status)}}</template></el-table-column><el-table-column prop="lastError" label="失败原因" min-width="180"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='FAILED'" @click="retry(row)" :disabled="task.busy.value">重试发奖</el-button></template></el-table-column></el-table><el-pagination v-if="rewardTotal>20" v-model:current-page="rewardPage" :total="rewardTotal" :page-size="20" layout="prev,pager,next" @current-change="details"/><el-dialog :model-value="!!editing" title="赛季奖励规则" @update:model-value="(v:boolean)=>{if(!v)editing=undefined;}"><el-form v-if="editing" label-position="top"><el-form-item label="起始名次"><el-input-number aria-label="起始名次" v-model="editing.rankFrom" :min="1"/></el-form-item><el-form-item label="结束名次"><el-input-number aria-label="结束名次" v-model="editing.rankTo" :min="editing.rankFrom"/></el-form-item><el-form-item label="奖励优惠券"><el-select aria-label="奖励优惠券" v-model="editing.couponId" filterable placeholder="选择优惠券"><el-option v-for="coupon in coupons" :key="coupon.id" :value="String(coupon.id)" :label="coupon.name"/></el-select></el-form-item><el-form-item label="启用发放"><el-switch aria-label="启用发放" v-model="editing.enabled"/></el-form-item></el-form><Status :error="task.error.value"/><template #footer><el-button @click="editing=undefined">取消</el-button><el-button type="primary" @click="save" :disabled="!editing?.couponId||task.busy.value">保存规则</el-button></template></el-dialog></section></template>